class _EvalError(Exception):
    pass


def calc(expr: str) -> int | str:
    n = len(expr)
    pos = 0

    def skip_spaces() -> None:
        nonlocal pos
        while pos < n and expr[pos] == " ":
            pos += 1

    def parse_add() -> int:
        nonlocal pos
        left = parse_mul()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in ("+", "-"):
                op = expr[pos]
                pos += 1
                right = parse_mul()
                left = left + right if op == "+" else left - right
            else:
                break
        return left

    def parse_mul() -> int:
        nonlocal pos
        left = parse_unary()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in ("*", "/", "%"):
                op = expr[pos]
                pos += 1
                right = parse_unary()
                if op == "*":
                    left = left * right
                else:
                    if right == 0:
                        raise _EvalError()
                    q = abs(left) // abs(right)
                    if (left < 0) ^ (right < 0):
                        q = -q
                    if op == "/":
                        left = q
                    else:
                        left = left - right * q
            else:
                break
        return left

    def parse_unary() -> int:
        nonlocal pos
        neg = False
        while True:
            skip_spaces()
            if pos < n and expr[pos] == "-":
                neg = not neg
                pos += 1
            else:
                break
        val = parse_power()
        return -val if neg else val

    def parse_power() -> int:
        nonlocal pos
        base = parse_primary()
        skip_spaces()
        if pos < n and expr[pos] == "^":
            pos += 1
            exp = parse_unary()
            if exp < 0:
                raise _EvalError()
            return base**exp
        return base

    def parse_primary() -> int:
        nonlocal pos
        skip_spaces()
        if expr[pos] == "(":
            pos += 1
            val = parse_add()
            skip_spaces()
            pos += 1  # consume ')'
            return val
        start = pos
        while pos < n and expr[pos].isdigit():
            pos += 1
        return int(expr[start:pos])

    try:
        return parse_add()
    except _EvalError:
        return "error"
